<div class="apo-activity" data-endpoint="{{ route('activity.notifications') }}" role="region" aria-label="Yeni mesaj, rezervasyon ve konaklama güncellemeleri">
 <a class="apo-activity-call" href="#" hidden></a><span class="apo-activity-status" aria-live="polite">Yeni mesajlar, rezervasyonlar ve pet durum güncellemeleri burada bildirilir.</span>
 <button type="button" class="apo-activity-toggle" aria-pressed="false">♬ Sesli uyarıyı aç</button>
</div>
<style>
.apo-activity{position:fixed;z-index:1000;right:16px;bottom:16px;display:flex;align-items:center;gap:10px;max-width:min(94vw,460px);padding:9px 10px 9px 14px;border:1px solid #dfe8e3;border-radius:999px;background:#fff;box-shadow:0 8px 28px #17362d20;color:#34423d;font:600 12px/1.35 system-ui,-apple-system,'Segoe UI',sans-serif}.apo-activity-status{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.apo-activity-toggle{flex:none;padding:8px 12px;border:0;border-radius:999px;background:#fff1ec;color:#b93616;font:700 12px system-ui;cursor:pointer}.apo-activity-toggle[aria-pressed=true]{background:#e7f4ed;color:#246544}@media(max-width:560px){.apo-activity{right:10px;bottom:10px;left:10px;justify-content:space-between}.apo-activity-status{max-width:56vw}}
.apo-activity-call{flex:none;max-width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding:8px 11px;border-radius:99px;background:#e83f18;color:#fff;font-weight:800;text-decoration:none}.apo-activity-call[hidden]{display:none!important}
</style>
<script>
(function(){
 const box=document.querySelector('.apo-activity');if(!box)return;
 const button=box.querySelector('button'),status=box.querySelector('[aria-live]'),callLink=box.querySelector('.apo-activity-call'),endpoint=box.dataset.endpoint;
 let enabled=localStorage.getItem('apo-activity-sound')==='1',audio=null;
 button.setAttribute('aria-pressed',enabled?'true':'false');button.textContent=enabled?'♬ Sesli uyarı açık':'♬ Sesli uyarıyı aç';
 button.addEventListener('click',async function(){enabled=!enabled;localStorage.setItem('apo-activity-sound',enabled?'1':'0');button.setAttribute('aria-pressed',enabled?'true':'false');button.textContent=enabled?'♬ Sesli uyarı açık':'♬ Sesli uyarıyı aç';if(enabled){try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();await audio.resume();status.textContent='Yeni mesaj ve rezervasyonlar sesli bildirilecek.';}catch(_){status.textContent='Tarayıcı ses izni vermedi; bildirimler ekranda gösterilecek.';}}else{status.textContent='Sesli uyarılar kapalı.';}});
 function beep(){if(!enabled)return;try{audio=audio||new (window.AudioContext||window.webkitAudioContext)();const now=audio.currentTime;[0,.18].forEach((delay,i)=>{const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.type='sine';oscillator.frequency.value=i?880:660;gain.gain.setValueAtTime(.0001,now+delay);gain.gain.exponentialRampToValueAtTime(.12,now+delay+.02);gain.gain.exponentialRampToValueAtTime(.0001,now+delay+.15);oscillator.connect(gain);gain.connect(audio.destination);oscillator.start(now+delay);oscillator.stop(now+delay+.16);});}catch(_){}}
 let notifiedCall=null;async function poll(){if(document.hidden)return;try{const response=await fetch(endpoint,{credentials:'same-origin',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'},cache:'no-store'});if(!response.ok)return;const result=await response.json(),messages=Number(result.messages||0),reservations=Number(result.reservations||0),updates=Number(result.stay_updates||0),total=messages+reservations+updates,call=result.incoming_call;if(call){callLink.href=call.url;callLink.textContent=call.label;callLink.hidden=false;if(notifiedCall!==call.url){beep();notifiedCall=call.url}}else{callLink.hidden=true;notifiedCall=null}if(total){const parts=[];if(messages)parts.push(messages+' yeni mesaj');if(reservations)parts.push(reservations+' yeni rezervasyon talebi');if(updates)parts.push(updates+' pet durum güncellemesi');status.textContent=parts.join(' · ');beep();}else if(!enabled&& !call)status.textContent='Yeni mesaj, rezervasyon ve pet durum güncellemeleri burada görünür.';}catch(_){}}
 poll();window.setInterval(poll,5000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)poll();});
})();
</script>
